  $motgjson${"slug": "motion-graphics", "title": "Motion Graphics", "description": "Motion Graphics is an advanced studio elective in animation for screen-based design. Students learn to design movement with intention: timing, spacing, sequence, typography, sound, After Effects workflow, brand motion, title design, explainers, UI microinteractions, and final delivery. The course combines short technical studies, critique, production documentation, and a polished portfolio-ready motion piece.", "topics": [{"id": "2c2d91a3-0e47-477f-be8b-dfd8245b23df", "type": "topic", "title": "Motion Graphics as Time-Based Visual Communication", "description": "This opening unit frames motion graphics as designed communication over time: typography, image, rhythm, sound, sequence, and screen context working together.", "children": [{"id": "3f796b28-4200-419b-8381-4bedc47c24d9", "type": "subtopic", "title": "Motion design roles and contexts", "children": [{"id": "6033a98b-f3aa-43c3-b055-0cc724f203d5", "type": "concept", "title": "motion designer"}, {"id": "58691a97-4673-4a33-af19-c2eb1e38f491", "type": "concept", "title": "broadcast package"}, {"id": "d186b13b-aac7-47a4-8444-1cf7b1d8cf27", "type": "concept", "title": "social video"}, {"id": "78cf6bf1-c377-4aca-9dfe-811151297adc", "type": "concept", "title": "UI animation"}, {"id": "db30873d-2201-4dcf-a43a-bee9bedd1b02", "type": "concept", "title": "event graphics"}, {"id": "3e63b4da-948b-4353-a4ce-0c5dea5407b4", "type": "concept", "title": "out-of-home screen"}], "description": "Students learn where motion graphics live across branding, advertising, UI, broadcast, film, social media, events, and public screens."}, {"id": "61c39c08-afd3-4999-90f0-f684d1a7d083", "type": "subtopic", "title": "Time as a design material", "children": [{"id": "28333cd3-94ce-4944-9a13-f3f1df585d6a", "type": "concept", "title": "duration"}, {"id": "f5539461-f0ab-4dcf-9a11-6e8351779b0e", "type": "concept", "title": "sequence"}, {"id": "9e862b12-6e34-4fae-82a6-f97b1ea8923d", "type": "concept", "title": "tempo"}, {"id": "d8629b99-7a71-40c0-90d9-8db8ded43315", "type": "concept", "title": "transition"}, {"id": "3f6742a5-bcd4-4246-9c16-7d17c30ed8c0", "type": "concept", "title": "loop"}, {"id": "3c98e1d3-b3c6-4aee-8c0e-199c872d7726", "type": "concept", "title": "temporal hierarchy"}], "description": "This subtopic introduces duration, sequence, transformation, rhythm, and pacing as core design elements."}, {"id": "710203e8-2c2c-483f-95a0-542e03471553", "type": "subtopic", "title": "Communication goals and audience", "children": [{"id": "0dad893d-f9ac-4bef-88bd-deaa016d7a8d", "type": "concept", "title": "message hierarchy"}, {"id": "059b59e3-73ef-4d24-9c86-5b7f8f93fcb0", "type": "concept", "title": "viewer attention"}, {"id": "4d0233c5-ced5-4782-adec-d8781126fafe", "type": "concept", "title": "call to action"}, {"id": "0572c562-c098-4c1d-8347-2e903862dfc2", "type": "concept", "title": "tone"}, {"id": "8816a91f-9f09-40c8-b94c-b875eef0e8e8", "type": "concept", "title": "brand voice"}, {"id": "a6725270-b65d-4636-8b12-4ff6b139f8bb", "type": "concept", "title": "context of use"}], "description": "Students connect motion choices to clarity, persuasion, emotion, brand voice, and viewer attention."}]}, {"id": "d0f2d1fe-80f4-4e21-a236-a958156efef0", "type": "topic", "title": "Principles of Animation for Designers", "description": "This unit translates classic animation principles into graphic design practice, emphasizing believable movement, expressive timing, and clear visual cause and effect.", "children": [{"id": "1d50c211-ecaa-4fb6-ad8d-a1343276bc7c", "type": "subtopic", "title": "Core animation principles", "children": [{"id": "d359a730-da40-4f43-b179-ce753e2cfa24", "type": "concept", "title": "squash and stretch"}, {"id": "dc79b559-dd7e-400e-88fc-9f6f64b0d404", "type": "concept", "title": "anticipation"}, {"id": "5fadac5a-287b-4a27-b35a-bcf348a1ffe1", "type": "concept", "title": "follow-through"}, {"id": "fb033723-1d02-4513-ba76-