set
  title = 'Motion Graphics',
  goal = 'Motion Graphics',
  summary = 'Motion Graphics is an advanced studio elective in animation for screen-based design. Students learn to design movement with intention: timing, spacing, sequence, typography, sound, After Effects workflow, brand motion, title design, explainers, UI microinteractions, and final delivery. The course combines short technical studies, critique, production documentation, and a polished portfolio-ready motion piece.',
  data = $motgjson${"slug": "motion-graphics", "title": "Motion Graphics", "description": "Motion Graphics is an advanced studio elective in animation for screen-based design. Students learn to design movement with intention: timing, spacing, sequence, typography, sound, After Effects workflow, brand motion, title design, explainers, UI microinteractions, and final delivery. The course combines short technical studies, critique, production documentation, and a polished portfolio-ready motion piece.", "topics": [{"id": "2c2d91a3-0e47-477f-be8b-dfd8245b23df", "type": "topic", "title": "Motion Graphics as Time-Based Visual Communication", "description": "This opening unit frames motion graphics as designed communication over time: typography, image, rhythm, sound, sequence, and screen context working together.", "children": [{"id": "3f796b28-4200-419b-8381-4bedc47c24d9", "type": "subtopic", "title": "Motion design roles and contexts", "children": [{"id": "6033a98b-f3aa-43c3-b055-0cc724f203d5", "type": "concept", "title": "motion designer"}, {"id": "58691a97-4673-4a33-af19-c2eb1e38f491", "type": "concept", "title": "broadcast package"}, {"id": "d186b13b-aac7-47a4-8444-1cf7b1d8cf27", "type": "concept", "title": "social video"}, {"id": "78cf6bf1-c377-4aca-9dfe-811151297adc", "type": "concept", "title": "UI animation"}, {"id": "db30873d-2201-4dcf-a43a-bee9bedd1b02", "type": "concept", "title": "event graphics"}, {"id": "3e63b4da-948b-4353-a4ce-0c5dea5407b4", "type": "concept", "title": "out-of-home screen"}], "description": "Students learn where motion graphics live across branding, advertising, UI, broadcast, film, social media, events, and public screens."}, {"id": "61c39c08-afd3-4999-90f0-f684d1a7d083", "type": "subtopic", "title": "Time as a design material", "children": [{"id": "28333cd3-94ce-4944-9a13-f3f1df585d6a", "type": "concept", "title": "duration"}, {"id": "f5539461-f0ab-4dcf-9a11-6e8351779b0e", "type": "concept", "title": "sequence"}, {"id": "9e862b12-6e34-4f